changeSet.sql:

IF EXISTS (SELECT 1 FROM sys.objects o
          INNER JOIN sys.columns c ON o.object_id = c.object_id
          WHERE o.name = 'RuleResult' AND c.name = 'PassFraction')
ALTER TABLE [dbo].[RuleResult] DROP COLUMN [PassFraction];

IF EXISTS (SELECT 1 FROM sys.objects o
          INNER JOIN sys.columns c ON o.object_id = c.object_id
          WHERE o.name = 'RuleResult' AND c.name = 'FailFraction')
ALTER TABLE [dbo].[RuleResult] DROP COLUMN [FailFraction];

IF EXISTS (SELECT 1 FROM sys.objects o
          INNER JOIN sys.columns c ON o.object_id = c.object_id
          WHERE o.name = 'RuleResult' AND c.name = 'Passed')
ALTER TABLE [dbo].[RuleResult] DROP COLUMN [Passed];

ALTER TABLE [dbo].[RuleResult] ADD [PassFraction]  AS (case when [RowsPassed]=(0) AND [RowsFailed]=(0) then (0) else CONVERT([decimal](18,17),CONVERT([decimal](18,3),[RowsPassed],(0))/(CONVERT([decimal](18,3),[RowsPassed],(0))+CONVERT([decimal](18,3),[RowsFailed],(0))),(0)) end);
ALTER TABLE [dbo].[RuleResult] ADD [FailFraction]  AS (case when [RowsPassed]=(0) AND [RowsFailed]=(0) then (0) when [RowsPassed]=(0) AND [RowsFailed]<>(0) then (1) else CONVERT([decimal](18,17),CONVERT([decimal](18,15),CONVERT([decimal](18,3),(1),(0))-CONVERT([decimal](18,3),[RowsPassed],(0))/(CONVERT([decimal](18,3),[RowsPassed],(0))+CONVERT([decimal](18,3),[RowsFailed],(0))),(0)),(0)) end);

