changeSet.sql:

CREATE OR ALTER FUNCTION [utility].[CalculatePassedWrapper]
(
	@PassFraction decimal(18,17),
	@RuleID int
)
RETURNS bit
AS
BEGIN
	RETURN [utility].CalculatePassed(@PassFraction, @RuleID)
END

